class Solution {
public:
    bool leafSimilar(TreeNode* root1, TreeNode* root2) {
        vector<TreeNode*> s1, s2;
        s1.push_back(root1);
        s2.push_back(root2);
        while (true) {
            bool has1, has2;
            int v1 = nextLeaf(s1, has1);
            int v2 = nextLeaf(s2, has2);
            if (!has1 && !has2) return true;
            if (!has1 || !has2) return false;
            if (v1 != v2) return false;
        }
    }
private:
    int nextLeaf(vector<TreeNode*>& s, bool& found) {
        found = false;
        while (!s.empty()) {
            TreeNode* node = s.back();
            s.pop_back();
            if (!node->left && !node->right) {
                found = true;
                return node->val;
            }
            if (node->right) s.push_back(node->right);
            if (node->left)  s.push_back(node->left);
        }
        return -1;
    }
};
